import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import ProcessGrid from './ProcessGrid';
import CreateProcessButton from './CreateProcessButton';

const HomePage = () => {
  const [processes, setProcesses] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchProcesses = async () => {
      setIsLoading(true);
      setError(null);
      try {
        const response = await fetch('/api/processes');
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setProcesses(data);
      } catch (err) {
        console.error("Failed to fetch processes:", err);
        setError(err.message || 'Failed to fetch processes. Check API connection.');
        setProcesses([]);
      } finally {
        setIsLoading(false);
      }
    };

    fetchProcesses();
  }, []);

  const handleCreateProcess = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const response = await fetch('/api/processes', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ general_description: 'New Untitled Process' }), 
      });
      if (!response.ok) {
        const errData = await response.json();
        throw new Error(errData.detail || `HTTP error! status: ${response.status}`);
      }
      const newProcess = await response.json();
      navigate(`/process/${newProcess.id}`);
    } catch (err) {
      console.error("Failed to create process:", err);
      setError(err.message || 'Failed to create process.');
    } finally {
      setIsLoading(false);
    }
  };

  const filteredProcesses = processes.filter(proc => {
    const searchTermLower = searchTerm.toLowerCase();
    const descriptionMatch = proc.general_description && proc.general_description.toLowerCase().includes(searchTermLower);
    const idMatch = proc.id && proc.id.toLowerCase().includes(searchTermLower);
    return descriptionMatch || idMatch;
  });

  const displayProcesses = searchTerm ? filteredProcesses : processes;

  const pageStyle = {
    padding: 'var(--spacing-unit, 16px)',
  };

  const controlsStyle = {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 'var(--spacing-unit, 16px)',
    flexWrap: 'wrap',
    gap: 'var(--spacing-unit, 16px)'
  };

  const searchInputStyle = {
    padding: '8px 12px',
    fontSize: '16px',
    border: '1px solid #ccc',
    borderRadius: 'var(--border-radius, 8px)',
    minWidth: '250px',
    flexGrow: 1
  };

  return (
    <div style={pageStyle}>
      <div style={controlsStyle}>
        <input 
          type="text" 
          placeholder="Search processes..." 
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={searchInputStyle}
        />
        <CreateProcessButton onClick={handleCreateProcess} />
      </div>

      {isLoading && <p>Loading...</p>}
      {error && <p style={{ color: 'red' }}>Error: {error}</p>}

      <ProcessGrid processes={displayProcesses.length > 0 || searchTerm ? displayProcesses : undefined} />
      {/* If displayProcesses is empty due to no API data AND no search term, 
          ProcessGrid will use its internal sample data. 
          If search yields no results from API data, it will show empty. 
      */}
    </div>
  );
};

export default HomePage;
